class Solution {
public:
    int minRemovals(vector<int>& nums, int target) {
        const int S = 1 << 14;
        vector<int> dp(S, -1000000);
        dp[0] = 0;
        for (int x : nums) {
            vector<int> next = dp;
            for (int mask = 0; mask < S; ++mask)
                if (dp[mask] >= 0)
                    next[mask ^ x] = max(next[mask ^ x], dp[mask] + 1);
            dp.swap(next);
        }
        return dp[target] < 0 ? -1 : (int)nums.size() - dp[target];
    }
};
